/**
 * Desktop Connector Extension
 *
 * Provides tools to interact with the Windows desktop: open apps,
 * system info, clipboard, notifications, and more.
 */

import type { Extension, ExtensionContext, CommandDefinition } from '@aiderdesk/extensions';
import { execSync, spawn } from 'child_process';

function runPowerShell(script: string): string {
  try {
    return execSync(`powershell -NoProfile -Command "${script.replace(/"/g, '\\"')}"`, {
      timeout: 15000,
      encoding: 'utf-8',
    }).trim();
  } catch (e: any) {
    return `Error: ${e.message}`;
  }
}

export default class DesktopConnector implements Extension {
  static metadata = {
    name: 'Desktop Connector',
    version: '1.0.0',
    description: 'Control your Windows desktop — open apps, clipboard, system info, screenshots, and more',
    author: 'AiderDesk User',
    capabilities: ['commands'],
  };

  async onLoad(context: ExtensionContext): Promise<void> {
    context.log('Desktop Connector loaded', 'info');
  }

  getCommands(_context: ExtensionContext): CommandDefinition[] {
    return [
      // --- Open App ---
      {
        name: 'desktop open-app',
        description: 'Open a Windows application (e.g. notepad, calculator, chrome, code)',
        arguments: [
          { description: 'Application name or path', required: true },
        ],
        execute: async ([app], ctx) => {
          const task = ctx.getTaskContext();
          const result = runPowerShell(`Start-Process "${app}" -PassThru`);
          task?.addLogMessage('info', `Launched: ${app}`);
        },
      },

      // --- System Info ---
      {
        name: 'desktop info',
        description: 'Show system information (OS, CPU, RAM, disk)',
        execute: async (_args, ctx) => {
          const task = ctx.getTaskContext();
          const os = runPowerShell('(Get-CimInstance Win32_OperatingSystem).Caption');
          const cpu = runPowerShell('(Get-CimInstance Win32_Processor).Name');
          const ram = runPowerShell('[math]::Round((Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory / 1GB, 1)');
          const free = runPowerShell('[math]::Round((Get-CimInstance Win32_OperatingSystem).FreePhysicalMemory / 1MB, 1)');
          task?.addLogMessage('info',
            `**System Info**\n- OS: ${os}\n- CPU: ${cpu}\n- RAM: ${ram} GB total, ${free} GB free`);
        },
      },

      // --- Clipboard Get ---
      {
        name: 'desktop clipboard',
        description: 'Get or set clipboard content. Usage: /desktop clipboard (get) or /desktop clipboard set <text>',
        arguments: [
          { description: 'Action: get or set', required: true },
          { description: 'Text to set (only for "set" action)', required: false },
        ],
        execute: async ([action, ...valueParts], ctx) => {
          const task = ctx.getTaskContext();
          if (action === 'get') {
            const content = runPowerShell('Get-Clipboard');
            task?.addLogMessage('info', `**Clipboard:** ${content || '(empty)'}`);
          } else if (action === 'set') {
            const text = valueParts.join(' ');
            runPowerShell(`Set-Clipboard -Value "${text.replace(/"/g, '\\"')}"`);
            task?.addLogMessage('info', 'Clipboard updated');
          }
        },
      },

      // --- Notification ---
      {
        name: 'desktop notify',
        description: 'Show a Windows toast notification',
        arguments: [
          { description: 'Notification title', required: true },
          { description: 'Notification message', required: true },
        ],
        execute: async ([title, ...msgParts], ctx) => {
          const task = ctx.getTaskContext();
          const message = msgParts.join(' ');
          const psScript = `
            [Windows.UI.Notifications.ToastNotificationManager, Windows.UI.Notifications, ContentType = WindowsRuntime] > $null
            $template = [Windows.UI.Notifications.ToastNotificationManager]::GetTemplateContent([Windows.UI.Notifications.ToastTemplateType]::ToastText02)
            $textNodes = $template.GetElementsByTagName("text")
            $textNodes.Item(0).AppendChild($template.CreateTextNode("${title.replace(/"/g, '\\"')}")) > $null
            $textNodes.Item(1).AppendChild($template.CreateTextNode("${message.replace(/"/g, '\\"')}")) > $null
            $toast = [Windows.UI.Notifications.ToastNotification]::new($template)
            [Windows.UI.Notifications.ToastNotificationManager]::CreateToastNotifier().Show($toast)
          `;
          runPowerShell(psScript);
          task?.addLogMessage('info', `Notification sent: ${title}`);
        },
      },

      // --- Screenshot ---
      {
        name: 'desktop screenshot',
        description: 'Take a screenshot and save it to desktop',
        arguments: [
          { description: 'Filename (without path, default: screenshot-{timestamp}.png)', required: false },
        ],
        execute: async ([filename], ctx) => {
          const task = ctx.getTaskContext();
          const name = filename || `screenshot-${Date.now()}.png`;
          const desktop = runPowerShell('[Environment]::GetFolderPath("Desktop")');
          const fullPath = `${desktop}\\${name}`;
          const psScript = `
            Add-Type -AssemblyName System.Windows.Forms
            Add-Type -AssemblyName System.Drawing
            $bounds = [System.Windows.Forms.Screen]::PrimaryScreen.Bounds
            $bitmap = New-Object System.Drawing.Bitmap $bounds.Width, $bounds.Height
            $graphics = [System.Drawing.Graphics]::FromImage($bitmap)
            $graphics.CopyFromScreen($bounds.X, $bounds.Y, 0, 0, $bounds.Size)
            $bitmap.Save("${fullPath}", [System.Drawing.Imaging.ImageFormat]::Png)
            $graphics.Dispose()
            $bitmap.Dispose()
          `;
          runPowerShell(psScript);
          task?.addLogMessage('info', `Screenshot saved: ${fullPath}`);
        },
      },

      // --- Run Command ---
      {
        name: 'desktop run',
        description: 'Run any PowerShell command on the desktop',
        arguments: [
          { description: 'PowerShell command to execute', required: true },
        ],
        execute: async ([...cmdParts], ctx) => {
          const task = ctx.getTaskContext();
          const cmd = cmdParts.join(' ');
          const result = runPowerShell(cmd);
          task?.addLogMessage('info', `**Result:**\n${result || '(no output)'}`);
        },
      },
    ];
  }
}

{
  "name": "browser-connector",
  "version": "1.0.0",
  "description": "Browser automation via Playwright — navigate, extract, click, fill, screenshot",
  "main": "index.ts",
  "keywords": ["aiderdesk", "extension", "browser"],
  "author": "AiderDesk User",
  "license": "MIT",
  "dependencies": {
    "playwright": "^1.62.0"
  }
}

/**
 * Browser Connector Extension
 *
 * Browser automation via Playwright — navigate, extract, click, fill, screenshot.
 */

import type { Extension, ExtensionContext, CommandDefinition } from '@aiderdesk/extensions';
import { chromium } from 'playwright';

let browser: any = null;

async function getBrowser() {
  if (!browser) {
    browser = await chromium.launch({ headless: true });
  }
  return browser;
}

async function getPage() {
  const b = await getBrowser();
  const pages = b.contexts()[0]?.pages() || [];
  if (pages.length > 0) return pages[0];
  const ctx = await b.newContext();
  return await ctx.newPage();
}

export default class BrowserConnector implements Extension {
  static metadata = {
    name: 'Browser Connector',
    version: '1.0.0',
    description: 'Browser automation via Playwright — navigate, extract, click, fill, screenshot',
    author: 'AiderDesk User',
    capabilities: ['commands'],
  };

  async onLoad(context: ExtensionContext): Promise<void> {
    context.log('Browser Connector loaded', 'info');
  }

  async onUnload(_context: ExtensionContext): Promise<void> {
    if (browser) {
      await browser.close();
      browser = null;
    }
  }

  getCommands(_context: ExtensionContext): CommandDefinition[] {
    return [
      // --- Navigate ---
      {
        name: 'browser goto',
        description: 'Navigate a browser tab to a URL',
        arguments: [
          { description: 'URL to navigate to (e.g. https://example.com)', required: true },
        ],
        execute: async ([url], ctx) => {
          const task = ctx.getTaskContext();
          try {
            const page = await getPage();
            await page.goto(url, { waitUntil: 'networkidle' });
            const title = await page.title();
            task?.addLogMessage('info', `Navigated to **${url}**\nPage title: ${title}`);
          } catch (e: any) {
            task?.addLogMessage('error', `Failed: ${e.message}`);
          }
        },
      },

      // --- Extract page content ---
      {
        name: 'browser extract',
        description: 'Extract text content from current page (or a specific selector)',
        arguments: [
          { description: 'Optional CSS selector (default: body)', required: false },
        ],
        execute: async ([selector], ctx) => {
          const task = ctx.getTaskContext();
          try {
            const page = await getPage();
            const sel = selector || 'body';
            const el = await page.$(sel);
            if (!el) {
              task?.addLogMessage('warning', `Selector not found: ${sel}`);
              return;
            }
            const text = await el.innerText();
            const title = await page.title();
            const url = page.url();
            task?.addLogMessage('info',
              `**Page:** ${title}\n**URL:** ${url}\n\n${text.slice(0, 4000)}`);
          } catch (e: any) {
            task?.addLogMessage('error', `Failed: ${e.message}`);
          }
        },
      },

      // --- Click ---
      {
        name: 'browser click',
        description: 'Click an element on the page by CSS selector',
        arguments: [
          { description: 'CSS selector of the element to click', required: true },
        ],
        execute: async ([selector], ctx) => {
          const task = ctx.getTaskContext();
          try {
