            await page.click(selector, { timeout: 10000 });
            task?.addLogMessage('info', `Clicked: ${selector}`);
          } catch (e: any) {
            task?.addLogMessage('error', `Failed: ${e.message}`);
          }
        },
      },

      // --- Fill ---
      {
        name: 'browser fill',
        description: 'Fill a form field by CSS selector',
        arguments: [
          { description: 'CSS selector of the input field', required: true },
          { description: 'Text to type into the field', required: true },
        ],
        execute: async ([selector, ...valueParts], ctx) => {
          const task = ctx.getTaskContext();
          const value = valueParts.join(' ');
          try {
            const page = await getPage();
            await page.fill(selector, value);
            task?.addLogMessage('info', `Filled "${selector}" with: ${value}`);
          } catch (e: any) {
            task?.addLogMessage('error', `Failed: ${e.message}`);
          }
        },
      },

      // --- Screenshot ---
      {
        name: 'browser screenshot',
        description: 'Take a screenshot of the current page and save to desktop',
        arguments: [
          { description: 'Filename (default: browser-screenshot-{timestamp}.png)', required: false },
        ],
        execute: async ([filename], ctx) => {
          const task = ctx.getTaskContext();
          try {
            const page = await getPage();
            const name = filename || `browser-screenshot-${Date.now()}.png`;
            const desktop = require('path').join(
              require('os').homedir(),
              'Desktop',
              name
            );
            await page.screenshot({ path: desktop, fullPage: false });
            task?.addLogMessage('info', `Screenshot saved: ${desktop}`);
          } catch (e: any) {
            task?.addLogMessage('error', `Failed: ${e.message}`);
          }
        },
      },

      // --- Get HTML ---
      {
        name: 'browser html',
        description: 'Get the full HTML of the current page (or a specific element)',
        arguments: [
          { description: 'Optional CSS selector (default: body)', required: false },
        ],
        execute: async ([selector], ctx) => {
          const task = ctx.getTaskContext();
          try {
            const page = await getPage();
            const sel = selector || 'body';
            const el = await page.$(sel);
            if (!el) {
              task?.addLogMessage('warning', `Selector not found: ${sel}`);
              return;
            }
            const html = await el.innerHTML();
            task?.addLogMessage('info', `**HTML** (${sel}):\n${html.slice(0, 4000)}`);
          } catch (e: any) {
            task?.addLogMessage('error', `Failed: ${e.message}`);
          }
        },
      },

      // --- Close browser ---
      {
        name: 'browser close',
        description: 'Close the browser instance and free resources',
        execute: async (_args, ctx) => {
          const task = ctx.getTaskContext();
          if (browser) {
            await browser.close();
            browser = null;
            task?.addLogMessage('info', 'Browser closed');
          } else {
            task?.addLogMessage('info', 'No browser open');
          }
        },
      },
    ];
  }
}

