const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ headless: false });
  const page = await browser.newPage();
  await page.goto('https://www.linkedin.com', { waitUntil: 'domcontentloaded' });
  console.log('Browser opened to LinkedIn. You can log in now.');
})().catch(e => console.error('Error:', e.message));

const { chromium } = require('playwright');
const path = require('path');

const userDataDir = path.join(process.env.USERPROFILE, '.aider-desk', 'browser-profile');

(async () => {
  const context = await chromium.launchPersistentContext(userDataDir, {
    headless: false,
    args: ['--remote-debugging-port=9222'],
  });
  const pages = context.pages();
  const page = pages[0] || await context.newPage();
  await page.goto('https://www.linkedin.com', { waitUntil: 'domcontentloaded' });
  console.log('Browser ready at LinkedIn with persistent profile.');

  // Keep alive
  process.stdin.resume();
})().catch(e => console.error('Error:', e.message));

const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.connectOverCDP('http://localhost:9222');
  const [page] = browser.contexts()[0]?.pages() || (await browser.newPage());
  await page.waitForTimeout(2000);

  // Scroll down a bit to load more feed
  await page.evaluate(() => window.scrollBy(0, 600));
  await page.waitForTimeout(1500);

  // Extract feed posts
  const posts = await page.evaluate(() => {
    const items = document.querySelectorAll('.feed-shared-update-v2__description, .update-components-text, .feed-shared-text, [data-urn]');
    const results = [];
    const seen = new Set();
    items.forEach(el => {
      const text = el.innerText?.trim();
      if (text && text.length > 20 && !seen.has(text)) {
        seen.add(text);
        results.push(text.slice(0, 600));
      }
    });
    return results.slice(0, 10);
  });

  // Also get author names
  const authors = await page.evaluate(() => {
    const els = document.querySelectorAll('.update-components-actor__title, .feed-shared-actor__name, .hoverable-link-text');
    return Array.from(els).map(e => e.innerText.trim()).filter(Boolean).slice(0, 10);
  });

  console.log('=== LINKEDIN FEED ===');
  console.log(JSON.stringify({ posts, authors }, null, 2));
  console.log('=== END FEED ===');

  await browser.close();
})().catch(e => console.error('Error:', e.message));

