    text: `100% agree. The margins are already razor-thin — the carriers who survive are the ones watching every dollar. At Dockly we see fleets bleeding money on everything from deadhead miles to outdated dispatch processes. Curious what you find is the #1 expense drain you encounter with owners?`
  }
];

(async () => {
  const browser = await chromium.connectOverCDP('http://localhost:9222');
  const context = browser.contexts()[0];
  const page = context?.pages()[0];
  if (!page) { console.log('No page found'); await browser.disconnect(); return; }

  for (const comment of COMMENTS) {
    try {
      console.log(`\n--- Commenting on ${comment.author}'s post ---`);

      // Find the post containing the author name
      const postBtn = await page.locator(`article:has-text("${comment.author}") button:has-text("Comment")`);
      // Try alternate selector
      let btn = await page.locator(`[data-urn]:has-text("${comment.author}") button:has-text("Comment")`).first();

      if (await btn.count() === 0) {
        btn = await page.locator(`article:has-text("${comment.author}") [aria-label*="Comment"]`).first();
      }
      if (await btn.count() === 0) {
        btn = await page.locator(`[data-urn]:has-text("${comment.author}") [aria-label*="Comment"]`).first();
      }

      if (await btn.count() === 0) {
        console.log(`Could not find comment button for ${comment.author}, trying generic approach...`);
        // Try finding by scanning feed items
        const allArticles = await page.locator('article').all();
        for (const article of allArticles) {
          const text = await article.innerText();
          if (text.includes(comment.author)) {
            const commentBtn = article.locator('button:has-text("Comment")').first();
            if (await commentBtn.count() > 0) {
              await commentBtn.click();
              break;
            }
          }
        }
      } else {
        await btn.click();
      }

      await page.waitForTimeout(2000);

      // Find the comment input - LinkedIn uses a rich text editor
      const editor = page.locator('div[role="textbox"][contenteditable="true"]').first();
      if (await editor.count() === 0) {
        console.log('Could not find comment editor');
        continue;
      }

      await editor.click();
      await page.waitForTimeout(500);

      // Type the comment character by character to avoid issues
      await editor.type(comment.text, { delay: 15 });

      await page.waitForTimeout(1000);

      // Click the "Post" or "Submit" button
      const postBtn2 = page.locator('button:has-text("Post")').first();
      if (await postBtn2.count() > 0) {
        await postBtn2.click();
        console.log(`Comment posted on ${comment.author}'s post!`);
      } else {
        // Try pressing Ctrl+Enter
        await page.keyboard.press('Control+Enter');
        console.log(`Comment submitted via keyboard for ${comment.author}'s post`);
      }

      await page.waitForTimeout(3000);
    } catch (e) {
      console.log(`Failed for ${comment.author}: ${e.message}`);
    }
  }

  console.log('\nDone posting comments.');
  await browser.disconnect();
})().catch(e => console.error('Error:', e.message));

