(async () => {
  // Connect to the LinkedIn feed page directly
  const browser = await chromium.connectOverCDP('http://localhost:9222');
  const target = browser.contexts();

  // Find the main page
  let feedPage = null;
  for (const ctx of target) {
    for (const p of ctx.pages()) {
      if (p.url().includes('linkedin.com/feed')) {
        feedPage = p;
        break;
      }
    }
    if (feedPage) break;
  }

  if (!feedPage) {
    console.log('Could not find LinkedIn feed page');
    await browser.disconnect();
    return;
  }

  console.log('Found feed page:', feedPage.url());

  for (const comment of COMMENTS) {
    try {
      console.log(`\n=== Posting comment to ${comment.name} ===`);

      // Scroll down to find the post
      await feedPage.evaluate(() => window.scrollTo(0, 0));
      await feedPage.waitForTimeout(1000);

      // Find all visible feed posts and get their text
      const found = await feedPage.evaluate((authorName) => {
        // Try to find the post containing the author name
        const allPosts = document.querySelectorAll('[data-urn]');
        for (const post of allPosts) {
          if (post.innerText.includes(authorName)) {
            // Find the comment button within this post
            const buttons = post.querySelectorAll('button');
            for (const btn of buttons) {
              if (btn.innerText.includes('Comment') && btn.offsetParent !== null) {
                // Scroll to it
                btn.scrollIntoView({ behavior: 'instant', block: 'center' });
                return { found: true, postId: post.getAttribute('data-urn') || 'unknown' };
              }
            }
          }
        }
        return { found: false };
      }, comment.name);

      if (!found.found) {
        console.log(`Could not find post or comment button for ${comment.name}`);
        continue;
      }

      await feedPage.waitForTimeout(1000);

      // Now click the comment button using JavaScript
      const clicked = await feedPage.evaluate((authorName) => {
        const allPosts = document.querySelectorAll('[data-urn]');
        for (const post of allPosts) {
          if (post.innerText.includes(authorName)) {
            const buttons = post.querySelectorAll('button');
            for (const btn of buttons) {
              if (btn.innerText.includes('Comment') && btn.offsetParent !== null) {
                btn.click();
                return true;
              }
            }
          }
        }
        return false;
      }, comment.name);

      if (!clicked) {
        console.log(`Failed to click comment button for ${comment.name}`);
        continue;
      }

      await feedPage.waitForTimeout(2000);

      // Type the comment
      const typed = await feedPage.evaluate((commentText) => {
        const editor = document.querySelector('div[role="textbox"][contenteditable="true"]');
        if (!editor) return false;
        editor.focus();
        // Use execCommand to insert text (more reliable than setting innerText)
        document.execCommand('insertText', false, commentText);
        return true;
      }, comment.text);

      if (!typed) {
        console.log('Could not find comment editor');
        continue;
      }

      await feedPage.waitForTimeout(1000);

      // Click the "Post" button
      const posted = await feedPage.evaluate(() => {
        const buttons = document.querySelectorAll('button');
        for (const btn of buttons) {
          if (btn.innerText.includes('Post') && btn.offsetParent !== null) {
            // Make sure it's the comment post button, not a feed post button
            const isCommentPost = btn.closest('.comments-comment-box') || 
                                 btn.closest('[data-control-name="comment_post"]');
            if (isCommentPost || btn.innerText.trim() === 'Post') {
              btn.click();
              return true;
            }
          }
        }
        // Try just "Post" button
        for (const btn of buttons) {
          if (btn.innerText.trim() === 'Post' && btn.offsetParent !== null) {
            btn.click();
            return true;
          }
        }
        return false;
      });

      if (posted) {
        console.log(`✅ Comment posted on ${comment.name}'s post!`);
      } else {
        // Try Ctrl+Enter
        await feedPage.keyboard.press('Control+Enter');
        console.log(`Submitted via keyboard for ${comment.name}`);
      }

      await feedPage.waitForTimeout(3000);
    } catch (e) {
      console.log(`Failed for ${comment.name}: ${e.message}`);
    }
  }

  console.log('\nDone!');
  await browser.disconnect();
})().catch(e => console.error('Error:', e.message));

