  }
];

(async () => {
  const context = await chromium.launchPersistentContext(userDataDir, {
    headless: true,
    args: ['--disable-blink-features=AutomationControlled'],
  });

  const page = context.pages()[0] || await context.newPage();

  // Navigate to feed
  await page.goto('https://www.linkedin.com/feed/', { waitUntil: 'networkidle', timeout: 30000 });
  console.log('Loaded feed');

  for (const comment of COMMENTS) {
    try {
      console.log(`\n=== Commenting on ${comment.name} ===`);

      // Scroll to top first
      await page.evaluate(() => window.scrollTo(0, 0));
      await page.waitForTimeout(2000);

      // Try clicking "Comment" on their post using text matching
      // Each feed item has the author name somewhere in it
      const result = await page.evaluate(({ authorName }) => {
        // Look for all feed posts by finding their feed containers
        const feedItems = document.querySelectorAll(
          '.feed-shared-update-v2, [data-urn], article, .occludable-update'
        );

        for (const item of feedItems) {
          const text = item.innerText || '';
          if (!text.includes(authorName)) continue;

          // Found the right post - now click the "Comment" button
          const buttons = item.querySelectorAll('button');
          for (const btn of buttons) {
            const btnText = btn.innerText.trim().toLowerCase();
            if ((btnText === 'comment' || btnText.startsWith('comment') || btnText.includes('comment')) && btn.offsetParent !== null) {
              btn.scrollIntoView({ block: 'center' });
              setTimeout(() => btn.click(), 100);
              return { step: 'clicked_comment', found: true };
            }
          }
        }

        // Fallback: search all buttons on the page
        const allButtons = document.querySelectorAll('button');
        for (const btn of allButtons) {
          if (btn.innerText.trim().toLowerCase() === 'comment' && btn.offsetParent !== null) {
            // Check if this button is near the author's post
            const parentText = btn.closest('[data-urn]')?.innerText || btn.closest('article')?.innerText || '';
            if (parentText.includes(authorName)) {
              btn.scrollIntoView({ block: 'center' });
              setTimeout(() => btn.click(), 100);
              return { step: 'clicked_comment_fallback', found: true };
            }
          }
        }

        return { step: 'not_found', found: false };
      }, { authorName: comment.name });

      console.log(`Comment button result:`, result);

      if (!result.found) {
        console.log(`Could not find comment button for ${comment.name}`);
        continue;
      }

      await page.waitForTimeout(3000);

      // Find and fill the comment editor
      const editorResult = await page.evaluate((commentText) => {
        const editor = document.querySelector('div[role="textbox"][contenteditable="true"]');
        if (!editor) return { found: false, reason: 'no editor' };

        editor.focus();
        document.execCommand('insertText', false, commentText);
        return { found: true };
      }, comment.text);

      if (!editorResult.found) {
        // Try clicking on the editor area
        const editors = await page.locator('div[role="textbox"]');
        const count = await editors.count();
        console.log(`Found ${count} textbox editors`);

        if (count > 0) {
          await editors.first().click();
          await page.waitForTimeout(500);
          await editors.first().fill(comment.text);
        } else {
          console.log('Could not find any text editor');
          continue;
        }
      }

      await page.waitForTimeout(1500);

      // Click Post button
      const posted = await page.evaluate(() => {
        const buttons = document.querySelectorAll('button');
        for (const btn of buttons) {
          const t = btn.innerText.trim();
          if (t === 'Post' && btn.offsetParent !== null) {
            // Check it's in the comment box or just the visible Post button
            const inCommentBox = btn.closest('.comments-comment-box, .comments-comment-texteditor');
            if (inCommentBox || btn.classList.contains('comments-post-button') || true) {
              btn.click();
              return true;
            }
          }
        }
        return false;
      });

      if (posted) {
        console.log(`✅ Comment posted on ${comment.name}'s post!`);
      } else {
        // Try Enter
        await page.keyboard.press('Control+Enter');
        console.log(`Submitted via Ctrl+Enter for ${comment.name}`);
      }

      await page.waitForTimeout(2000);
    } catch (e) {
      console.log(`Failed for ${comment.name}: ${e.message}`);
    }
  }

  console.log('\nDone posting!');
  await context.close();
})().catch(e => { console.error('Fatal:', e.message); process.exit(1); });

