const { chromium } = require('playwright');
const path = require('path');

const userDataDir = path.join(process.env.USERPROFILE, '.aider-desk', 'browser-profile');

(async () => {
  const context = await chromium.launchPersistentContext(userDataDir, {
    headless: false,
    args: ['--disable-blink-features=AutomationControlled'],
  });

  const page = context.pages()[0] || await context.newPage();
  await page.goto('https://www.linkedin.com/feed/', { waitUntil: 'domcontentloaded', timeout: 60000 });

  // Scroll to load content
  for (let i = 0; i < 5; i++) {
    await page.evaluate(() => window.scrollBy(0, 800));
    await page.waitForTimeout(2000);
  }
  await page.evaluate(() => window.scrollTo(0, 0));
  await page.waitForTimeout(2000);

  // Get the main content area
  const structure = await page.evaluate(() => {
    // Get all main divs/containers
    const main = document.querySelector('main') || document.querySelector('.scaffold-layout__main');
    if (!main) return 'No main element found';

    // Get all direct child elements in the main content
    const children = main.querySelectorAll(':scope > div, :scope > section');
    const result = [];
    children.forEach((el, i) => {
      const tag = el.tagName;
      const id = el.id || '-';
      const classes = (el.className || '').slice(0, 100);
      const firstChildTag = el.children[0]?.tagName || '-';
      const innerText = (el.innerText || '').slice(0, 150);
      result.push({ i, tag, id, classes, firstChildTag, innerText });
    });
    return result;
  });

  console.log('=== Main Content Structure ===');
  console.log(JSON.stringify(structure, null, 2));

  // Also look for any element containing "Patrick Smith"
  const patrickElements = await page.evaluate(() => {
    const all = document.querySelectorAll('*');
    const results = [];
    for (const el of all) {
      if (el.children.length > 0) continue; // Only leaf elements
      const text = el.innerText?.trim() || '';
      if (text.includes('Patrick Smith') && text.length < 100) {
        const parent = el.parentElement;
        results.push({
          tag: el.tagName,
          text: text.slice(0, 100),
          parentTag: parent?.tagName || '-',
          parentClass: (parent?.className || '').slice(0, 80),
          grandparentTag: parent?.parentElement?.tagName || '-',
        });
      }
    }
    return results.slice(0, 20);
  });

  console.log('\n=== Elements containing "Patrick Smith" ===');
  console.log(JSON.stringify(patrickElements, null, 2));

  await page.waitForTimeout(5000);
  console.log('\nBrowser staying open so you can see it. Close manually when done.');
  // Keep alive
  process.stdin.resume();
})().catch(e => { console.error('Fatal:', e.message); process.exit(1); });

