    },
    {
      name: 'Natasha Williams',
      text: `100% agree. The margins are already razor-thin — the carriers who survive are the ones watching every dollar. At Dockly we see fleets bleeding money on everything from deadhead miles to outdated dispatch processes. Curious what you find is the #1 expense drain you encounter with owners?`
    }
  ];

  for (const comment of COMMENTS) {
    console.log(`\n--- Commenting on ${comment.name} ---`);

    // Find the post and click Comment
    const found = await page.evaluate((authorName) => {
      // Try various selectors for feed items
      const selectors = [
        '.feed-shared-update-v2',
        '[data-urn]',
        'article',
        '.occludable-update',
        '.scaffold-finite-scroll__content > div',
      ];

      for (const sel of selectors) {
        const items = document.querySelectorAll(sel);
        for (const item of items) {
          if (item.innerText && item.innerText.includes(authorName)) {
            const buttons = item.querySelectorAll('button');
            for (const btn of buttons) {
              const bt = btn.innerText.trim().toLowerCase();
              if (bt === 'comment' || bt.startsWith('comment')) {
                btn.scrollIntoView({ block: 'center' });
                setTimeout(() => btn.click(), 100);
                return true;
              }
            }
          }
        }
      }
      return false;
    }, comment.name);

    if (!found) {
      console.log(`Could not find comment button for ${comment.name}`);
      continue;
    }

    await new Promise(r => setTimeout(r, 3000));

    // Fill comment
    const filled = await page.evaluate((text) => {
      const editor = document.querySelector('div[role="textbox"][contenteditable="true"]');
      if (!editor) return false;
      editor.focus();
      document.execCommand('insertText', false, text);
      return true;
    }, comment.text);

    if (!filled) {
      console.log('Could not fill editor');
      continue;
    }

    await new Promise(r => setTimeout(r, 1500));

    // Click Post
    const posted = await page.evaluate(() => {
      const buttons = document.querySelectorAll('button');
      for (const btn of buttons) {
        if (btn.innerText.trim() === 'Post' && btn.offsetParent !== null) {
          btn.click();
          return true;
        }
      }
      return false;
    });

    if (posted) {
      console.log(`✅ Comment posted on ${comment.name}`);
    } else {
      await page.keyboard.press('Control+Enter');
      console.log(`Submitted via keyboard for ${comment.name}`);
    }

    await new Promise(r => setTimeout(r, 3000));
  }

  console.log('\n✅ All comments posted!');
  await browser.close();
})().catch(e => { console.error('Fatal:', e.message); process.exit(1); });

